import React, { useEffect, useState, useCallback, useRef } from "react";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";
import { apisPath, paths } from "../../utils/path";
import { useLocation, useNavigate } from "react-router-dom";
import http from "../../services/utility";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { useDispatch } from "react-redux";
import {
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  Button,
} from "@mui/material";

export default function SubCategories() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { state } = useLocation();
  const [brandId, setBrandId] = useState(state?.brandId);
  const [catId, setCatId] = useState(state?.id);
  const [catName, setCatName] = useState(state?.name);
  const [catImage, setCatImage] = useState(state?.image);
  const [cardData, setCardData] = useState([]);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);
  const [hasNextPage, setHasNextPage] = useState(true);
  const observerRef = useRef(null);
  const loadingRef = useRef(null);

  // Modal state
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [subcategoryToDelete, setSubcategoryToDelete] = useState(null);

  useEffect(() => {
    getData(1, true);
  }, []);

  // Infinite scroll logic
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        const target = entries[0];
        if (target.isIntersecting && hasNextPage && !loading) {
          getData(page + 1, false);
        }
      },
      { threshold: 0.1 }
    );

    if (loadingRef.current) {
      observer.observe(loadingRef.current);
    }

    observerRef.current = observer;

    return () => {
      if (observerRef.current) {
        observerRef.current.disconnect();
      }
    };
  }, [hasNextPage, loading, page]);

  const loadMoreData = useCallback(() => {
    if (hasNextPage && !loading) {
      getData(page + 1, false);
    }
  }, [hasNextPage, loading, page]);

  const getData = async (pageNum = 1, isInitial = false) => {
    if (loading) return;
    setLoading(true);

    try {
      const response = await http.get(`https://api.bignlean.com/admin/all-subcategories?page=${pageNum}`);
      let data = response?.data?.subcategories;

      // Filter subcategories by catId if needed
      if (catId) {
        data = data.filter(sub => sub.catId === catId);
      }

      // Fetch products for each subcategory
        for (let i = 0; i < data.length; i++) {
        try {
          const productResponse = await http.get(
            `${apisPath?.admin?.products}?catId=${data[i]?.catId}&subCatId=${data[i]?.id}`
          );
          data[i]["items"] = productResponse?.data?.products;
        } catch (err) {
              console.log(err);
          data[i]["items"] = [];
        }
      }

      if (isInitial) {
        setCardData(data);
        setInitialLoading(false);
      } else {
        setCardData(prev => [...prev, ...data]);
      }

      // Check if there are more pages
      const pagination = response?.data?.pagination;
      setHasNextPage(pagination?.hasNextPage || false);
      setPage(pageNum);

    } catch (err) {
        console.log(err);
      dispatch(
        openTicker({ title: "Error", body: err?.response?.data?.message || "Failed to load subcategories" })
      );
      setInitialLoading(false);
    } finally {
      setLoading(false);
    }
  };

  const openDeleteModal = (subcategory) => {
    setSubcategoryToDelete(subcategory);
    setDeleteModalOpen(true);
  };

  const handleCloseDeleteModal = () => {
    setDeleteModalOpen(false);
    setSubcategoryToDelete(null);
  };

  const confirmDelete = async () => {
    if (!subcategoryToDelete) return;

    await http
      .delete(`${apisPath?.admin?.subcategories}?id=${subcategoryToDelete.id}`)
      .then(async (res) => {
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        // Reset and reload data after deletion
        setPage(1);
        setHasNextPage(true);
        setCardData([]);
        getData(1, true);
        handleCloseDeleteModal();
      })
      .catch((err) => {
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
        handleCloseDeleteModal();
      });
  };

  return (
    <div className="sub_categories">
      <div className="sub_categories__heading">
        <h3 className="sub_categories__heading_text page_heading">Sub Categories</h3>
        <button
          className="button-red"
          onClick={() =>
            navigate(
              `/${paths?.front?.user?.products}/${paths?.front?.user?.sub_categories}/${paths?.front?.user?.add_sub_categories}`,
              {
                state: { data: [], addSubCat: true, catId: catId },
              }
            )
          }
        >
          Add New Sub Category
        </button>
      </div>
      <div className="sub_categories__content">
        <div className="sub_categories__content__sub_categories_list">
          <div className="sub_categories__content__sub_categories_list__content">
            {initialLoading ? (
              <div className="loading_progress">
                <div className="loading_spinner"></div>
                <p>Loading subcategories...</p>
              </div>
            ) : cardData?.length > 0 ? (
              cardData?.map((data, index) => {
                return (
                  <SubCategoryCard
                    key={`${data?.id}-${index}`}
                    data={data}
                    deleteData={() => openDeleteModal(data)}
                    catId={catId}
                    image={catImage}
                  />
                );
              })
            ) : (
              <div className="no_data_found">No Data Found</div>
            )}
            {/* Invisible element for intersection observer */}
            <div ref={loadingRef} style={{ height: '10px' }} />
          </div>
        </div>
      </div>

      {/* Delete Confirmation Modal */}
      <Dialog
        open={deleteModalOpen}
        onClose={handleCloseDeleteModal}
        aria-labelledby="delete-dialog-title"
        aria-describedby="delete-dialog-description"
        className="sub_categories__delete_modal"
        disablePortal={false}
        container={document.body}
        style={{
          position: 'fixed',
          zIndex: 9999999,
        }}
        BackdropProps={{
          style: {
            position: 'fixed',
            zIndex: 9999998,
          },
        }}
      >
        <DialogTitle id="delete-dialog-title">Delete Sub Category</DialogTitle>
        <DialogContent>
          <div className="delete-icon-container">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M19 7L18.1327 19.1425C18.0579 20.1891 17.187 21 16.1378 21H7.86224C6.81296 21 5.94208 20.1891 5.86732 19.1425L5 7M10 11V17M14 11V17M15 7V4C15 3.44772 14.5523 3 14 3H10C9.44772 3 9 3.44772 9 4V7M4 7H20" stroke="#dc2626" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </div>
          <DialogContentText id="delete-dialog-description">
            Are you sure you want to delete <strong>"{subcategoryToDelete?.name}"</strong>?
          </DialogContentText>
          <DialogContentText>
            This action cannot be undone. All associated data will be permanently removed.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDeleteModal} variant="outlined" className="cancel-btn">
            Cancel
          </Button>
          <Button onClick={confirmDelete} variant="contained" className="delete-btn">
            Delete Sub Category
          </Button>
        </DialogActions>
      </Dialog>
    </div>
  );
}

const SubCategoryCard = ({ data, deleteData, catId, image }) => {
  const navigate = useNavigate();

  return (
    <div className="sub_categories_list_card">
      <div className="sub_categories_list_card__content">
        {image ? (
          <img src={image} alt={data?.name} />
        ) : (
          <div className="sub_categories_list_card__content__text">
            {data?.name}
          </div>
        )}
      </div>
      <div style={{ display: 'flex', gap: '10px', flexDirection: 'column' }}>
        <button
          className="button-border-red"
          onClick={() => {
            navigate(
              `/${paths?.front?.user?.products}/${paths?.front?.user?.sub_categories}/${paths?.front?.user?.add_sub_categories}`,
              {
                state: { data: data, addSubCat: false, catId: catId },
              }
            );
          }}
        >
          Edit
        </button>
        <button className="button-red" onClick={deleteData}>
          Delete
        </button>
      </div>
    </div>
  );
};
